// Feature Flag system — every UI feature controlled by backend on/off switch
// Admin can disable any module → it disappears from frontend completely

export type FeatureScope = "student" | "teacher" | "admin" | "all";
export type FeatureCategory =
  | "booking" | "membership" | "ai" | "community" | "gamification"
  | "wellness" | "campaign" | "notification" | "payment" | "analytics"
  | "integration" | "content" | "teacher" | "hr" | "coupon" | "pricing"
  | "ecommerce" | "referral" | "survey" | "carousel" | "chat" | "ads" | "journey"
  | "yoga" | "enterprise" | "mcp_admin" | "security" | "crm"
  | "identity" | "qr" | "social" | "mcp" | "student";

export interface FeatureFlagProps {
  key: string;           // e.g. "yoga.ai_coach", "booking.waitlist"
  name: string;          // human-readable
  description: string;
  category: FeatureCategory;
  scope: FeatureScope;
  enabled: boolean;
  rolloutPercent: number;   // 0-100 for gradual rollout; 100 = full
  allowedRoles: string[];   // if empty, applies to all roles in scope
  metadata: Record<string, unknown>;
  updatedBy: string;
  updatedAt: Date;
}

export class FeatureFlag {
  constructor(private props: FeatureFlagProps) {
    if (!props.key.match(/^[a-z][a-z0-9_.]+$/))
      throw new Error("Feature key must be lowercase with dots/underscores, e.g. 'booking.waitlist'");
    if (props.rolloutPercent < 0 || props.rolloutPercent > 100)
      throw new Error("Rollout percent must be 0–100");
  }

  get key()            { return this.props.key; }
  get name()           { return this.props.name; }
  get description()    { return this.props.description; }
  get category()       { return this.props.category; }
  get scope()          { return this.props.scope; }
  get enabled()        { return this.props.enabled; }
  get rolloutPercent() { return this.props.rolloutPercent; }
  get allowedRoles()   { return [...this.props.allowedRoles]; }
  get updatedBy()      { return this.props.updatedBy; }
  get updatedAt()      { return this.props.updatedAt; }

  isEnabledFor(role: string, userIdHash?: number): boolean {
    if (!this.props.enabled) return false;
    if (this.props.allowedRoles.length > 0 && !this.props.allowedRoles.includes(role)) return false;
    if (this.props.rolloutPercent === 100) return true;
    if (userIdHash !== undefined) return (userIdHash % 100) < this.props.rolloutPercent;
    return true;
  }

  enable(updatedBy: string): FeatureFlag {
    return new FeatureFlag({ ...this.props, enabled: true, updatedBy, updatedAt: new Date() });
  }

  disable(updatedBy: string): FeatureFlag {
    return new FeatureFlag({ ...this.props, enabled: false, updatedBy, updatedAt: new Date() });
  }

  setRollout(percent: number, updatedBy: string): FeatureFlag {
    if (percent < 0 || percent > 100) throw new Error("Rollout percent must be 0–100");
    return new FeatureFlag({ ...this.props, rolloutPercent: percent, updatedBy, updatedAt: new Date() });
  }

  toJSON(): FeatureFlagProps {
    return { ...this.props, allowedRoles: [...this.props.allowedRoles] };
  }
}

